#!/bin/sh
# Generated by EnvKit Packer: prepare the app, then supervise everything.
# Turn a part off with RUN_WEB / RUN_QUEUE / RUN_SCHEDULER / RUN_REVERB=false.
set -e
cd /var/www/html
export RUN_WEB="${RUN_WEB:-true}" RUN_QUEUE="${RUN_QUEUE:-true}" RUN_SCHEDULER="${RUN_SCHEDULER:-true}" RUN_REVERB="${RUN_REVERB:-true}"
if [ "${DB_CONNECTION:-mysql}" = "sqlite" ]; then
  touch database/database.sqlite
fi
if [ "${RUN_MIGRATIONS:-true}" = "true" ]; then
  # The database container may still be starting: retry for ~40 s.
  n=0
  until php artisan migrate --force --no-interaction; do
    n=$((n + 1))
    if [ "$n" -ge 20 ]; then echo "EnvKit: migrations skipped (database not reachable)"; break; fi
    sleep 2
  done
fi
chown -R www-data:www-data storage bootstrap/cache database
exec supervisord -c /etc/supervisord.conf
